import{_ as t,o as i,c as n,a2 as a}from"./chunks/framework.CRkDNIZq.js";const u=JSON.parse('{"title":"Project Pitch: Real-Time Usage & Metered Billing Engine","description":"","frontmatter":{},"headers":[],"relativePath":"00b-project-pitch.md","filePath":"00b-project-pitch.md"}'),r={name:"00b-project-pitch.md"};function o(c,e,s,l,d,g){return i(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="project-pitch-real-time-usage-metered-billing-engine" tabindex="-1">Project Pitch: Real-Time Usage &amp; Metered Billing Engine <a class="header-anchor" href="#project-pitch-real-time-usage-metered-billing-engine" aria-label="Permalink to &quot;Project Pitch: Real-Time Usage &amp; Metered Billing Engine&quot;">​</a></h1><h2 id="_30-second-elevator-pitch" tabindex="-1">30-Second Elevator Pitch <a class="header-anchor" href="#_30-second-elevator-pitch" aria-label="Permalink to &quot;30-Second Elevator Pitch&quot;">​</a></h2><blockquote><p>&quot;I designed and built <strong>19-Usage-Billing-Engine</strong>, an enterprise-grade metered billing, rating, and invoicing platform in Python FastAPI, PostgreSQL, and React. It solves the critical financial risk of usage-based pricing by providing an idempotent ingestion pipeline that guarantees exactly-once billing under network retries. It features a multi-tiered rating engine supporting graduated and volume pricing calculated to exact integer cents, an append-only double-entry ledger that strictly enforces debit-credit conservation, and automated billing cycle reconciliation with gapless invoice numbering.&quot;</p></blockquote><hr><h2 id="_2-minute-technical-interview-pitch" tabindex="-1">2-Minute Technical Interview Pitch <a class="header-anchor" href="#_2-minute-technical-interview-pitch" aria-label="Permalink to &quot;2-Minute Technical Interview Pitch&quot;">​</a></h2><blockquote><p>&quot;As SaaS companies transition from flat subscriptions to usage-based models, their billing infrastructure faces severe reliability challenges: duplicate events caused by network retries, floating-point rounding errors on micro-transactions, and complex mid-cycle plan upgrades requiring exact pro-rata math.</p><p>To solve these challenges, I engineered a high-throughput, audit-proof billing platform.</p><p>At the edge, in <code>metering/ingestion.py</code>, the ingestion pipeline handles high-volume telemetry events like API calls or GPU compute seconds. Every event is checked against a cryptographic idempotency key index in PostgreSQL. If client network timeouts cause retries, our system recognizes duplicate keys in constant time and returns the cached confirmation, preventing double-billing without dropping valid traffic.</p><p>In <code>rating/engine.py</code>, the rating engine evaluates accumulated raw usage against dynamic customer price books. It supports flat rates, per-unit metering, volume discounts, and graduated slab tiers—where the first 1,000 units might be free, the next 10,000 cost 2 cents, and beyond costs 1 cent. All mathematical operations are calculated in integer minor units (cents) or fixed-point Decimal with <code>ROUND_HALF_UP</code>, eliminating floating-point rounding drift.</p><p>In <code>invoicing/manager.py</code>, when a billing period closes, the invoice manager locks customer meters, aggregates usage rollups, applies promotional discounts and taxes, and assigns a gapless sequential invoice number (<code>INV-YYYY-XXXX</code>) using row-level locking.</p><p>Crucially, every financial mutation is synchronized with an append-only double-entry ledger in <code>models/ledger.py</code>. Every ledger transaction enforces that the sum of debits strictly equals the sum of credits across at least two entries, guaranteeing accounting compliance.</p><p>The frontend provides an interactive billing console with real-time KPI metrics and invoice inspection. The entire architecture is verified by 87 automated tests covering timestamp drift rejection, differential rollup reconciliation, and dunning schedules.&quot;</p></blockquote>',6)])])}const h=t(r,[["render",o]]);export{u as __pageData,h as default};
